import 'dart:io';

import 'package:path/path.dart' as p;

/// The header every file `beak generate` owns starts with.
const String beakGeneratedHeader =
    '// GENERATED BY beak generate — DO NOT EDIT.';

/// What syncing the generated files did.
final class GenerateSyncResult {
  /// Creates a result.
  const GenerateSyncResult({
    this.written = const [],
    this.unchanged = const [],
    this.removed = const [],
    this.problems = const [],
  });

  /// Files whose contents changed.
  final List<String> written;

  /// Files already up to date.
  final List<String> unchanged;

  /// Generated files nothing produces any more.
  final List<String> removed;

  /// Why `--check` failed, or what stopped a run.
  final List<String> problems;
}

/// A folder whose generated files `beak generate` owns.
final class GeneratedArea {
  /// Creates an area.
  ///
  /// With [partsOnly], only `*.beak.dart` files in [directory] are generated
  /// (a definitions package's own `lib/`); otherwise every `.dart` file is,
  /// and one without [beakGeneratedHeader] stops the run.
  const GeneratedArea(
    this.directory, {
    this.partsOnly = false,
    this.exclude = const [],
  });

  /// The folder.
  final Directory directory;

  /// Whether only part files are generated here.
  final bool partsOnly;

  /// Folders another [GeneratedArea] owns, skipped by this one.
  final List<Directory> exclude;
}

/// Writes [files] (absolute path to contents) and removes the generated
/// files in [areas] nothing produces any more. [check] writes nothing and
/// reports what would change.
GenerateSyncResult syncGeneratedFiles(
  Map<String, String> files,
  List<GeneratedArea> areas, {
  required bool check,
}) {
  final written = <String>[];
  final unchanged = <String>[];
  final removed = <String>[];
  final problems = <String>[];
  for (final entry in files.entries) {
    final file = File(entry.key);
    final current = file.existsSync() ? file.readAsStringSync() : null;
    if (current == entry.value) {
      unchanged.add(file.path);
      continue;
    }
    if (check) {
      problems.add(
        current == null ? 'missing: ${file.path}' : 'stale: ${file.path}',
      );
    } else {
      file
        ..parent.createSync(recursive: true)
        ..writeAsStringSync(entry.value);
      written.add(file.path);
    }
  }
  final expected = {for (final path in files.keys) p.normalize(path)};
  for (final area in areas) {
    if (!area.directory.existsSync()) continue;
    for (final entity in area.directory.listSync(recursive: true)) {
      if (entity is! File) continue;
      final path = p.normalize(entity.path);
      if (area.exclude.any((folder) => p.isWithin(folder.path, path))) {
        continue;
      }
      final generated = area.partsOnly
          ? path.endsWith('.beak.dart')
          : path.endsWith('.dart');
      if (!generated || expected.contains(path)) continue;
      final source = entity.readAsStringSync();
      if (!source.startsWith(beakGeneratedHeader)) {
        if (!area.partsOnly) {
          problems.add(
            'orphan: ${entity.path} is not generated; move it out of the '
            'generated folder.',
          );
        }
        continue;
      }
      if (check) {
        problems.add('orphan: ${entity.path}');
      } else {
        entity.deleteSync();
        removed.add(entity.path);
      }
    }
  }
  return GenerateSyncResult(
    written: written,
    unchanged: unchanged,
    removed: removed,
    problems: problems,
  );
}
